question.answer:
package main

import "sync"

type Scale struct {
	mu    sync.Mutex
	total int
}

func (s *Scale) Add(kilos int) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.total += kilos
}

func (s *Scale) Total() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.total
}

func weigh(bins []int) int {
	var s Scale
	var wg sync.WaitGroup
	for _, kilos := range bins {
		wg.Go(func() {
			s.Add(kilos)
		})
	}
	wg.Wait()
	return s.Total()
}

testcode.text:
bins := make([]int, 2000)
for i := range bins {
	bins[i] = 1
}
total := 0
for range 50 {
	total += weigh(bins)
}
fmt.Println(total, weigh(nil), weigh([]int{}))

