question.answer:
package main

import (
	"context"
	"errors"
	"time"
)

func harbour() (context.Context, context.CancelFunc) {
	return context.WithCancel(context.Background())
}

func curfew() (context.Context, context.CancelFunc) {
	return context.WithDeadline(context.Background(), time.Now().Add(-time.Hour))
}

func clearance(ctx context.Context) string {
	err := ctx.Err()
	if err == nil {
		return "sail"
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return "expired"
	}
	return "recalled"
}

