question.answer:
package main

import (
	"context"
	"sync"
)

func shift() (context.Context, context.CancelFunc) {
	return context.WithCancel(context.Background())
}

func rounds(ctx context.Context, radio <-chan string) ([]string, error) {
	var reached []string
	for {
		if err := ctx.Err(); err != nil {
			return reached, err
		}
		select {
		case stop, ok := <-radio:
			if !ok {
				return reached, nil
			}
			reached = append(reached, stop)
		case <-ctx.Done():
			return reached, ctx.Err()
		}
	}
}

func dispatch(ctx context.Context, stops []string) ([]string, error) {
	radio := make(chan string)
	var wg sync.WaitGroup
	wg.Go(func() {
		defer close(radio)
		for _, stop := range stops {
			select {
			case radio <- stop:
			case <-ctx.Done():
				return
			}
		}
	})
	reached, err := rounds(ctx, radio)
	wg.Wait()
	return reached, err
}
